const body = $json.body ?? $json;
return [{
  json: {
    event: body.event ?? 'unknown',
    lead_name: body.lead_name ?? '',
    business_type: body.business_type ?? '',
    channel: body.channel ?? '',
    need_summary: body.need_summary ?? '',
    extracted_budget_usd: body.extracted_budget_usd ?? 0,
    lead_score: body.lead_score ?? '',
    intent: body.intent ?? '',
    booked_slot: body.booked_slot ?? '',
    tokens_used: body.tokens_used ?? 0,
    cost_usd: body.cost_usd ?? 0,
    source: body.source ?? 'growpilot',
    received_at: new Date().toISOString(),
  },
}];
